import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # 使用集合统计不同的款式编号
    types = set()
    for _ in range(n):
        types.add(int(next(it)))

    ans = min(k, len(types))
    print(ans)

if __name__ == "__main__":
    main()
```

### Java

